    app?.classList.add("hidden"); shell.classList.remove("hidden");
    const consumer = loadConsumerState(); consumer.buyerUid ||= `BUY${String(Date.now()).slice(-7)}${Math.floor(Math.random()*100).toString().padStart(2,"0")}`; saveConsumerState(consumer);
    shell.innerHTML = `<div class="consumer-app"><aside class="consumer-nav"><a class="brand" href="#consumer-home"><span class="brand-mark"><svg viewBox="0 0 48 48"><path d="M24 6c-8 7-13 14-13 22 0 8 5 14 13 14s13-6 13-14C37 20 32 13 24 6Z" fill="none" stroke="currentColor" stroke-width="3"/><path d="M24 16v22M24 25c-4-2-7-4-9-7M24 30c4-2 7-4 9-7" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg></span><span class="brand-copy"><strong>Bhoomi<span>NOVA</span></strong><small>Consumer experience</small></span></a><nav class="consumer-nav-list"><button class="active" data-consumer-view="home" type="button">⌂ Home</button><button data-consumer-view="discover" type="button">◌ Discover farmers</button><button data-consumer-view="products" type="button">▣ Products</button><button data-consumer-view="favorites" type="button">♡ Favorites</button><button data-consumer-view="requests" type="button">↗ Requests & history</button><button data-consumer-view="notifications" type="button">◎ Notifications</button><button data-consumer-view="settings" type="button">⚙ Profile</button></nav><button id="consumerSwitchBtn" class="btn btn-secondary btn-full consumer-switch" type="button">Switch experience</button></aside><main class="consumer-main"><span class="section-kicker">PUBLIC FARM NETWORK · LOCAL MODE</span><h1>Fresh harvest, with trusted context.</h1><p>Discover only farmer-approved public information. Private boundaries, sensors, irrigation, family data and farm analytics remain outside this workspace.</p><span class="consumer-uid">Public Buyer UID · ${escapeHtml(consumer.buyerUid)} · Local profile</span><section id="consumerViewPanel" class="consumer-view-panel hidden"></section><section class="consumer-workflow-card"><div class="consumer-workflow-head"><div><span class="panel-kicker">PUBLIC FARM DISCOVERY</span><h2>Find a farmer by Public UID</h2></div><span class="pill pill-green">Approved data only</span></div><form id="consumerSearchForm" class="consumer-search-form"><input id="consumerFarmerSearch" inputmode="numeric" maxlength="10" placeholder="Enter 10-digit Farmer Public UID" aria-label="Farmer Public UID"><button class="btn btn-primary" type="submit">Search</button></form><div id="consumerSearchResult" class="consumer-result"><strong>Search a farmer to view public profile, crops and availability.</strong><small>Exact location and private farm telemetry are never shown.</small></div></section><div class="consumer-grid"><article class="consumer-card"><span class="stat-icon">⌖</span><strong>Discover farmers</strong><small>Search farmer-approved Public UID profiles and general regions.</small></article><article class="consumer-card"><span class="stat-icon amber">♧</span><strong>Fresh harvest</strong><small>View approved crop, harvest and availability information.</small></article><article class="consumer-card"><span class="stat-icon blue">✓</span><strong>Quality information</strong><small>Review farmer-approved notes, separate from consumer ratings.</small></article><article class="consumer-card"><span class="stat-icon rose">♡</span><strong>${consumer.favorites.length} favorites</strong><small>Save approved farmers and products for later.</small></article><article class="consumer-card"><span class="stat-icon violet">↗</span><strong>${consumer.requests.length} requests</strong><small>Track enquiries and purchase-interest requests locally.</small></article><article class="consumer-card"><span class="stat-icon">i</span><strong>Privacy boundary</strong><small>Consumer access excludes maps, sensors, AI reports, family data and settings.</small></article></div><section class="consumer-history-card"><div class="consumer-workflow-head"><div><span class="panel-kicker">CONSUMER ACTIVITY</span><h2>Recent requests</h2></div><span class="pill pill-neutral">${consumer.history.length} viewed</span></div><div id="consumerActivityList" class="consumer-activity-list">${consumer.requests.length ? consumer.requests.map((item) => `<div><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.status)} · ${escapeHtml(formatTime(item.createdAt))}</small></div>`).join("") : "<p class=\"panel-subtext\">No enquiries yet. Search an approved farmer to start a connection request.</p>"}</div></section></main></div>`;
    $("#consumerSwitchBtn")?.addEventListener("click", switchExperience);
    $$("[data-consumer-view]").forEach((button) => button.addEventListener("click", () => { $$("[data-consumer-view]").forEach((item) => item.classList.toggle("active", item === button)); renderConsumerView(button.dataset.consumerView, consumer); }));
    const restoredConsumerView=localStorage.getItem("bhoominova_consumer_route_v1"); if(restoredConsumerView && restoredConsumerView !== "home") { const restoredButton=$(`[data-consumer-view="${restoredConsumerView}"]`); restoredButton?.classList.add("active"); renderConsumerView(restoredConsumerView, consumer); }
    $("#consumerSearchForm")?.addEventListener("submit", (event) => { event.preventDefault(); const query=$("#consumerFarmerSearch")?.value.trim(); const farmer=state.workspace.profile; const result=$("#consumerSearchResult"); if (!result) return; consumer.history.unshift({ query, viewedAt: nowIso() }); consumer.history=consumer.history.slice(0,25); saveConsumerState(consumer); if (farmer?.publicListing && query === farmer.publicUid) { result.innerHTML=`<div class="consumer-public-profile"><strong>${escapeHtml(farmer.name || "Approved farmer")}</strong><span>${escapeHtml(farmer.crop || "Crop")} · ${escapeHtml(farmer.district || farmer.state || "General region")}</span><small>Farmer-approved public profile. Harvest availability and quality notes are integration-ready; exact location and private telemetry are hidden.</small><div><button id="consumerFavoriteBtn" class="btn btn-secondary" type="button">♡ Save favorite</button><button id="consumerEnquireBtn" class="btn btn-primary" type="button">Connect / enquire</button></div></div>`; $("#consumerFavoriteBtn")?.addEventListener("click",()=>{ if(!consumer.favorites.includes(query)) consumer.favorites.push(query); saveConsumerState(consumer); toast("Farmer saved to consumer favorites."); }); $("#consumerEnquireBtn")?.addEventListener("click",()=>{ consumer.requests.unshift({id:`request-${Date.now()}`,title:`Enquiry · ${farmer.crop || "approved harvest"}`,status:"PENDING FARMER RESPONSE",createdAt:nowIso(),farmerUid:query}); saveConsumerState(consumer); addEvent("system","Consumer enquiry created","A local consumer interest request was recorded; no external message was sent."); renderConsumerWorkspace(); toast("Interest request saved locally. Provider delivery is integration-ready."); }); } else { result.innerHTML="<strong>No approved public farmer found.</strong><small>Search uses the farmer's public UID and never reveals private account data.</small>"; } });
